function imgFor(category: string, slug: string): string {
  const pool = IMG[category] ?? IMG["SEO Strategy"];
  let hash = 0;
  for (let i = 0; i < slug.length; i++) hash = ((hash * 31) + slug.charCodeAt(i)) & 0xfffffff;
  return pool[hash % pool.length];
}

// ─── date spread: 1 day per post back from 2026-05-21 ───────────────────────
const MONTHS2 = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
function dateFor2(index: number): { date: string; iso: string; updated: string } {
  const anchor = new Date("2026-05-21T00:00:00Z");
  const d = new Date(anchor.getTime() - index * 24 * 60 * 60 * 1000);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  const day = d.getUTCDate();
  const iso = `${y}-${String(m + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
  const date = `${MONTHS2[m]} ${day}, ${y}`;
  const upd = new Date(Math.min(anchor.getTime(), d.getTime() + 45 * 24 * 60 * 60 * 1000));
  const updated = `${upd.getUTCFullYear()}-${String(upd.getUTCMonth() + 1).padStart(2, "0")}-${String(upd.getUTCDate()).padStart(2, "0")}`;
  return { date, iso, updated };
}

function readingTime2(intro: string[], sections: BlogSection[], takeaway: string): string {
  let words = intro.join(" ").split(/\s+/).length + takeaway.split(/\s+/).length;
  for (const s of sections) {
    words += s.h.split(/\s+/).length + s.p.join(" ").split(/\s+/).length;
    if (s.list) words += s.list.join(" ").split(/\s+/).length;
  }
  return `${Math.max(3, Math.round(words / 200))} min read`;
}

