const aiGuides: GuideInput[] = [
  { slug: "ai-overviews-ranking-factors-guide", category: "GEO", title: "AI Overviews Ranking Factors: How to Get Featured", subject: "AI Overviews ranking factors", hookA: "Google's AI Overviews now sit above the traditional results for many searches. Understanding what feeds them is the new front line of SEO.", whatIs: "AI Overviews ranking factors are the signals that influence which content Google synthesises into its AI-generated answers.", why: "AI Overviews capture attention before users reach the links. Being a source for them protects visibility as the results page changes.", steps: ["Rank well organically, since overviews draw from top results.", "Answer questions directly and clearly.", "Use clean heading structure and answer blocks.", "Build topical authority and E-E-A-T.", "Add schema to reinforce meaning."], link: "our GEO services", faqA: "Rank well organically first, since AI Overviews draw from pages that already perform, then answer questions directly with clear structure. Topical authority and E-E-A-T strengthen your inclusion.", faqTopic: "AI Overviews optimisation" },
  { slug: "zero-click-search-strategy-2026", category: "GEO", title: "Zero-Click Search Strategy for 2026", subject: "a zero-click search strategy", hookA: "More searches than ever end without a click. Instead of fighting that, the smartest brands are turning zero-click results into visibility and trust.", whatIs: "A zero-click search strategy adapts to searches that are answered directly on the results page.", why: "Zero-click results still build awareness and authority. Owning the answer keeps your brand visible even when the click does not happen.", steps: ["Optimise for snippets and AI answers.", "Build brand recognition within results.", "Capture clicks where deeper intent remains.", "Use results-page visibility to drive branded search.", "Measure impressions and brand lift, not just clicks."], link: "our GEO services", faqA: "Accept that many searches end on the results page, then optimise to own those answers so your brand stays visible. Capture clicks where deeper intent remains, and measure brand lift alongside traffic.", faqTopic: "zero-click search" },
  { slug: "llm-optimization-guide", category: "GEO", title: "LLM Optimisation: Making Your Brand AI-Ready", subject: "LLM optimisation", hookA: "Large language models are becoming a primary way people discover businesses. Optimising for them is no longer optional for forward-looking brands.", whatIs: "LLM optimisation structures your brand and content so large language models understand and recommend you.", why: "LLMs answer more buyer questions every day. Being understood and trusted by them determines whether you appear in those answers.", steps: ["Make your entity and offering unmistakably clear.", "Keep brand information consistent across the web.", "Publish authoritative, citable content.", "Earn mentions on trusted third-party sources.", "Add schema that reinforces who you are."], link: "our GEO services", faqA: "Make your brand and offering unmistakably clear, keep your information consistent across the web, and publish citable content. LLMs reward entities they can understand and verify from multiple sources.", faqTopic: "LLM optimisation" },
  { slug: "brand-search-optimization-guide", category: "SEO Strategy", title: "Brand Search Optimisation: Owning Your Own Name", subject: "brand search optimisation", hookA: "When someone searches your brand name, what they see shapes their entire first impression. Brand search optimisation makes sure that impression is strong.", whatIs: "Brand search optimisation controls and improves the search results that appear for your brand name.", why: "Branded searches come from your most interested prospects. Owning those results builds trust and protects against competitors and negative content.", steps: ["Ensure your site ranks first for your brand.", "Optimise your knowledge panel and profiles.", "Manage reviews and reputation results.", "Create content for branded queries.", "Monitor your branded SERP regularly."], link: "our SEO services", faqA: "Make sure your own site, profiles, and knowledge panel dominate the results for your brand name, then manage reviews and reputation. Branded searchers are your warmest prospects, so the first impression matters.", faqTopic: "brand search optimisation" },
  { slug: "entity-seo-complete-guide", category: "SEO Strategy", title: "Entity SEO: Optimising for How Search Understands Meaning", subject: "entity SEO", hookA: "Modern search engines think in entities, not just keywords. Entity SEO aligns your brand with how Google and AI tools actually understand the world.", whatIs: "Entity SEO optimises your brand as a clearly defined entity that search engines and AI tools can understand and connect.", why: "Search has shifted from strings to things. Being a well-defined entity helps you rank, earn knowledge panels, and get cited by AI.", steps: ["Define your brand entity clearly on your site.", "Keep entity information consistent everywhere.", "Use Organization and Person schema.", "Build presence in trusted knowledge sources.", "Connect related entities through content."], link: "our SEO services", faqA: "Define your brand as a clear entity on your site, keep that information consistent everywhere, and use Organization schema. Search now understands things rather than just strings, so entity clarity is key.", faqTopic: "entity SEO" },
  { slug: "knowledge-graph-optimization-guide", category: "SEO Strategy", title: "Knowledge Graph Optimisation for Brand Authority", subject: "knowledge graph optimisation", hookA: "Getting into Google's Knowledge Graph turns your brand into a recognised entity, complete with a knowledge panel. Here is how to earn that recognition.", whatIs: "Knowledge graph optimisation builds the signals that help Google recognise your brand as a known entity.", why: "Knowledge graph presence powers knowledge panels and feeds AI understanding of your brand. It is a foundation for both SEO and GEO.", steps: ["Establish consistent entity information.", "Use structured data to define your brand.", "Build presence in authoritative references.", "Earn mentions that confirm your entity.", "Claim and optimise your knowledge panel."], link: "our GEO services", faqA: "Build consistent entity signals through structured data, authoritative references, and mentions that confirm who you are. Over time these help Google recognise your brand and may earn you a knowledge panel.", faqTopic: "knowledge graph optimisation" },
  { slug: "eeat-building-guide", category: "SEO Strategy", title: "Building E-E-A-T: Experience, Expertise, Authority, Trust", subject: "building E-E-A-T", hookA: "Google increasingly rewards content that demonstrates real experience and expertise. Building E-E-A-T is how you prove yours, on the page and across the web.", whatIs: "E-E-A-T is Google's framework for assessing the experience, expertise, authoritativeness, and trustworthiness of content.", why: "E-E-A-T matters most for topics that affect health, finances, and safety, but it strengthens trust everywhere. It also shapes how AI tools judge your content.", steps: ["Demonstrate first-hand experience in your content.", "Showcase genuine author expertise and credentials.", "Build authority through citations and mentions.", "Add trust signals like reviews and clear policies.", "Keep content accurate and well-sourced."], link: "our content services", faqA: "Demonstrate real experience and expertise in your content, show author credentials, and build authority through citations and trust signals. E-E-A-T is shown through evidence, not claimed in words.", faqTopic: "E-E-A-T building" },
  { slug: "author-authority-building-guide", category: "SEO Strategy", title: "Author Authority: Why Who Writes Your Content Matters", subject: "author authority building", hookA: "Search engines and AI tools increasingly care who wrote your content. Building author authority turns your experts into a genuine ranking asset.", whatIs: "Author authority building establishes the credibility of the people behind your content.", why: "Credible, identifiable authors strengthen E-E-A-T and trust. Recognised expertise helps content rank and earns AI citations.", steps: ["Create detailed, credible author bios.", "Link authors to their credentials and profiles.", "Use Person schema for key authors.", "Build each author's presence across the web.", "Attribute content to real, qualified people."], link: "our content services", faqA: "Create detailed author bios, link to credentials and profiles, and use Person schema. Building a recognisable expert presence across the web strengthens both your E-E-A-T and your content's credibility.", faqTopic: "author authority" },
  { slug: "website-authority-signals", category: "SEO Strategy", title: "Website Authority Signals That Search Engines Trust", subject: "website authority signals", hookA: "Authority is not a single number, it is a collection of signals search engines piece together. Knowing which ones matter helps you build them deliberately.", whatIs: "Website authority signals are the factors that indicate how trustworthy and credible a site is.", why: "Authoritative sites rank more easily and get cited more often. Building the right signals lifts your whole domain, not just one page.", steps: ["Earn quality, relevant backlinks.", "Build consistent brand mentions across the web.", "Demonstrate expertise through deep content.", "Add trust signals and clear policies.", "Maintain technical health and security."], link: "our SEO services", faqA: "Build quality backlinks, consistent brand mentions, deep expert content, and clear trust signals. Authority is a collection of signals rather than one metric, so develop them together over time.", faqTopic: "authority signals" },
  { slug: "ai-content-seo-guide", category: "Content", title: "AI Content and SEO: Using It Without Getting Penalised", subject: "AI content and SEO", hookA: "AI can speed up content production, but used carelessly it produces thin, generic pages that go nowhere. The difference is in how you use it.", whatIs: "AI content and SEO covers how to use AI tools to support content without harming search performance.", why: "Google rewards helpful content regardless of how it is made, but punishes low-value mass production. Smart use of AI augments human expertise rather than replacing it.", steps: ["Use AI to assist, not to replace expertise.", "Add genuine insight, experience, and accuracy.", "Edit and fact-check everything thoroughly.", "Ensure content serves real user needs.", "Avoid mass-producing thin pages."], link: "our content services", faqA: "Use AI to assist research and drafting, but add genuine expertise, edit carefully, and fact-check everything. Google rewards helpful content regardless of origin, but penalises thin, mass-produced pages.", faqTopic: "AI content" },
  { slug: "human-vs-ai-content-seo", category: "Content", title: "Human vs AI Content: What Actually Ranks", subject: "the human versus AI content question", hookA: "The debate over human versus AI content misses the point. Search engines do not reward the author, they reward the value. Here is what that means in practice.", whatIs: "This guide compares human and AI content through the lens of what search engines actually reward.", why: "The origin of content matters less than its quality, accuracy, and usefulness. Understanding this lets you use both human and AI strengths wisely.", steps: ["Focus on value, not on how content is made.", "Use humans for experience, judgement, and originality.", "Use AI for scale, structure, and speed.", "Always add genuine expertise and accuracy.", "Measure performance, not production method."], link: "our content services", faqA: "Search engines reward value, accuracy, and usefulness rather than the author. Use human strengths for experience and originality and AI for speed and structure, but never publish thin, unedited output.", faqTopic: "content quality" },
  { slug: "content-quality-signals-2026", category: "Content", title: "Content Quality Signals That Matter in 2026", subject: "content quality signals", hookA: "Google has spent years getting better at recognising genuinely helpful content. The signals it uses are clearer than ever, if you know where to look.", whatIs: "Content quality signals are the indicators search engines use to judge how helpful and trustworthy content is.", why: "As algorithms mature, quality signals carry more weight. Aligning with them protects you from updates and earns durable rankings.", steps: ["Satisfy search intent completely.", "Demonstrate real experience and expertise.", "Keep content accurate and well-sourced.", "Structure for readability and extraction.", "Maintain engagement and usefulness over time."], link: "our content services", faqA: "Satisfy intent fully, demonstrate genuine experience, keep content accurate, and structure it clearly. As algorithms mature, these quality signals carry more weight and protect you from updates.", faqTopic: "content quality signals" },
  { slug: "helpful-content-guide", category: "Content", title: "Creating Helpful Content That Survives Every Update", subject: "helpful content", hookA: "Every major Google update rewards the same thing: content made for people, not search engines. Building genuinely helpful content is the only update-proof strategy.", whatIs: "Helpful content is content created primarily to satisfy and serve people rather than to manipulate rankings.", why: "Google's systems increasingly reward people-first content and demote content made just for search. Helpfulness is the most durable ranking strategy there is.", steps: ["Write for a real audience and their goals.", "Answer questions fully and honestly.", "Demonstrate genuine expertise and experience.", "Avoid writing solely for search engines.", "Keep content current and trustworthy."], link: "our content services", faqA: "Write primarily for your real audience, answer their questions fully, and demonstrate genuine expertise. Content made to serve people rather than manipulate rankings is the most update-proof strategy.", faqTopic: "helpful content" },
  { slug: "search-intent-optimization-2026", category: "SEO Strategy", title: "Search Intent Optimisation: The Core of Modern SEO", subject: "search intent optimisation", hookA: "You can do everything else right and still fail if your content misreads intent. Matching intent is the foundation everything else in SEO is built on.", whatIs: "Search intent optimisation aligns content precisely with the goal behind each search.", why: "Search engines rank content that satisfies intent above content that merely matches keywords. Misreading intent is one of the most common reasons pages fail.", steps: ["Analyse what currently ranks for a query.", "Identify the dominant intent behind it.", "Match your content type to that intent.", "Satisfy the full scope of the query.", "Reassess as intent shifts over time."], link: "our SEO services", faqA: "Study what already ranks to identify the dominant intent, then match your content type and depth to it. Misreading intent is a leading cause of pages that never rank despite good optimisation.", faqTopic: "search intent" },
  { slug: "passage-ranking-optimization-guide", category: "SEO Strategy", title: "Passage Ranking: How Google Ranks Parts of Pages", subject: "passage ranking optimisation", hookA: "Google can now rank a single passage from a long page for a specific query. That changes how you should structure content for maximum visibility.", whatIs: "Passage ranking is Google's ability to rank a specific section of a page for a relevant query.", why: "Passage ranking means well-structured sections can rank even on broad pages. Clear, self-contained passages multiply your ranking opportunities.", steps: ["Structure content into clear, focused sections.", "Use descriptive headings for each passage.", "Make each section self-contained and complete.", "Answer specific sub-questions directly.", "Avoid burying answers in dense blocks."], link: "our SEO services", faqA: "Structure content into clear, focused sections with descriptive headings so each passage can stand alone. Google can rank individual sections, so well-organised pages gain extra ranking opportunities.", faqTopic: "passage ranking" },
  { slug: "multisearch-seo-guide", category: "SEO Strategy", title: "Multisearch and Visual Search Optimisation", subject: "multisearch optimisation", hookA: "People now search with images and text together. Multisearch is reshaping discovery, especially for products, and most brands are unprepared.", whatIs: "Multisearch optimisation prepares your content and images for combined visual and text searches.", why: "Visual and multisearch are growing fast, particularly in retail. Optimised images and product data capture this emerging discovery channel.", steps: ["Optimise images with quality and descriptive data.", "Add detailed product and image structured data.", "Use clear, descriptive alt text and file names.", "Ensure strong image quality and context.", "Keep product information complete and accurate."], link: "our ecommerce SEO services", faqA: "Optimise your images with quality, descriptive alt text, and structured data, and keep product information complete. Visual and multisearch are growing fast, especially in retail discovery.", faqTopic: "multisearch optimisation" },
  { slug: "zero-party-data-seo-guide", category: "SEO Strategy", title: "Zero-Party Data and the Future of SEO Targeting", subject: "zero-party data and SEO", hookA: "As tracking tightens, the data customers willingly share becomes priceless. Zero-party data is reshaping how smart brands understand search demand.", whatIs: "Zero-party data is information customers intentionally share, used to sharpen content and targeting.", why: "With privacy changes limiting tracking, first-hand customer data guides better content decisions. It reveals real intent that keyword tools miss.", steps: ["Collect preferences through surveys and forms.", "Use customer input to shape content topics.", "Identify the real questions customers ask.", "Align content with stated needs.", "Respect privacy and consent throughout."], link: "our content services", faqA: "Collect the preferences and questions customers willingly share through surveys and forms, then use that to shape content. As tracking tightens, this first-hand insight guides better content decisions.", faqTopic: "zero-party data" },
  { slug: "brand-serp-optimization", category: "SEO Strategy", title: "Brand SERP Optimisation: Controlling Your First Impression", subject: "brand SERP optimisation", hookA: "The page someone sees when they Google your brand is your real homepage in the eyes of a prospect. Optimising it shapes every first impression.", whatIs: "Brand SERP optimisation manages everything that appears when people search your brand name.", why: "Your branded results form a critical first impression for warm prospects. Controlling them builds trust and steers attention where you want it.", steps: ["Dominate the first page with owned properties.", "Optimise your knowledge panel.", "Manage reviews and third-party results.", "Add sitelinks-friendly site structure.", "Monitor and refresh your branded SERP."], link: "our SEO services", faqA: "Fill your branded results with owned properties, optimise your knowledge panel, and manage reviews and third-party listings. These results shape the first impression for your warmest prospects.", faqTopic: "brand SERP optimisation" },
  { slug: "chatgpt-search-optimization", category: "GEO", title: "ChatGPT Search Optimisation: Getting Recommended", subject: "ChatGPT search optimisation", hookA: "Millions now ask ChatGPT for recommendations instead of searching Google. Showing up in those answers is a new and very real growth channel.", whatIs: "ChatGPT search optimisation structures your brand and content so ChatGPT recommends and cites you.", why: "ChatGPT influences a growing share of buying decisions. Being recommended there reaches customers who may never run a traditional search.", steps: ["Build clear, consistent entity information.", "Publish authoritative, well-structured content.", "Earn mentions on trusted third-party sources.", "Add schema that clarifies your brand.", "Test and track your visibility in ChatGPT."], link: "our GEO services", faqA: "Build clear entity information, publish authoritative content, and earn mentions on trusted sources, then test your visibility by asking ChatGPT relevant questions. Consistency across the web drives recommendations.", faqTopic: "ChatGPT optimisation" },
  { slug: "search-market-trends-2026", category: "SEO Strategy", title: "Search Market Trends Shaping SEO in 2026", subject: "search market trends", hookA: "Search is changing faster than at any point in its history. Knowing where it is heading lets you invest ahead of the curve instead of chasing it.", whatIs: "This guide outlines the major trends reshaping search and what they mean for your strategy.", why: "Understanding where search is heading helps you allocate effort wisely. The brands that adapt early to AI search and answer engines gain a lasting edge.", steps: ["Invest in AI search and GEO visibility.", "Optimise for answer engines and snippets.", "Strengthen brand and entity signals.", "Prioritise genuine expertise and trust.", "Keep technical and experience fundamentals strong."], link: "our SEO services", faqA: "The biggest shifts are the rise of AI search, answer engines, and zero-click results. Invest early in GEO and AEO while keeping your SEO fundamentals strong, since the underlying quality signals still apply.", faqTopic: "search trends" },
];
