const eeatGuides: GuideInput[] = [
  { slug: "eeat-for-ymyl-pages", category: "SEO Strategy", title: "E-E-A-T for YMYL Pages: Earning Trust Where It Counts", subject: "E-E-A-T for YMYL pages", hookA: "Pages that affect health, money, or safety face the toughest scrutiny in search. For these Your Money or Your Life topics, E-E-A-T is not optional, it is the price of ranking.", whatIs: "YMYL pages cover topics that can affect a person's health, finances, or safety, and they demand the highest E-E-A-T standards.", why: "Google holds YMYL content to a higher bar because the stakes are real. Strong experience, expertise, and trust signals are essential to rank here.", steps: ["Attribute content to qualified experts.", "Cite authoritative sources for every claim.", "Show credentials, reviews, and trust signals.", "Keep content accurate and up to date.", "Make contact and policy information clear."], link: "our content services", faqA: "Attribute content to qualified experts, cite authoritative sources, and display credentials and trust signals. YMYL topics affect health and finances, so Google demands strong, verifiable E-E-A-T.", faqTopic: "YMYL E-E-A-T" },
  { slug: "eeat-for-medical-websites", category: "SEO Strategy", title: "E-E-A-T for Medical Websites and Health Content", subject: "E-E-A-T for medical websites", hookA: "Health content carries real consequences, and Google treats it that way. Medical websites that win rankings do so by proving genuine expertise at every level.", whatIs: "E-E-A-T for medical websites establishes the expertise and trust health content requires to rank.", why: "Medical misinformation is dangerous, so Google heavily favours qualified, well-sourced health content. E-E-A-T is the deciding factor in this niche.", steps: ["Have content written or reviewed by professionals.", "Display credentials clearly.", "Cite peer-reviewed and authoritative sources.", "Keep medical information current.", "Add strong trust and contact signals."], link: "our content services", faqA: "Have qualified professionals write or review your content, display their credentials, and cite authoritative sources. Google scrutinises health content heavily, so verifiable medical expertise is essential.", faqTopic: "medical E-E-A-T" },
  { slug: "eeat-for-legal-websites", category: "SEO Strategy", title: "E-E-A-T for Legal Websites and Law Firms", subject: "E-E-A-T for legal websites", hookA: "Legal advice carries weight and risk, so search engines demand proof of expertise. Law firms that rank well demonstrate authority, not just assert it.", whatIs: "E-E-A-T for legal websites builds the expertise and trust signals legal content needs to rank.", why: "Legal content can affect serious decisions, so Google favours qualified, credible sources. Demonstrating real legal expertise is what wins rankings here.", steps: ["Attribute content to qualified legal professionals.", "Display credentials and bar admissions.", "Cite relevant statutes and authoritative sources.", "Keep legal information current and jurisdiction-specific.", "Add reviews and clear trust signals."], link: "our content services", faqA: "Attribute content to qualified lawyers, display their credentials, and cite relevant statutes and sources. Legal topics carry real consequences, so Google rewards demonstrated, verifiable expertise.", faqTopic: "legal E-E-A-T" },
  { slug: "eeat-for-financial-websites", category: "SEO Strategy", title: "E-E-A-T for Financial Websites and Advice", subject: "E-E-A-T for financial websites", hookA: "Financial content shapes decisions about people's money, and Google knows it. Building strong E-E-A-T is the only reliable path to ranking financial advice.", whatIs: "E-E-A-T for financial websites establishes the credibility financial content needs to rank.", why: "Financial advice carries real risk, so Google favours qualified, transparent sources. E-E-A-T is the deciding factor for ranking in finance.", steps: ["Have qualified professionals create the content.", "Display credentials and regulatory status.", "Cite authoritative financial sources.", "Be transparent about risks and disclaimers.", "Keep information accurate and current."], link: "our content services", faqA: "Have qualified professionals create your content, display credentials and any regulatory status, and be transparent about risk. Google holds financial advice to a high standard, so credibility is decisive.", faqTopic: "financial E-E-A-T" },
  { slug: "expertise-signals-seo", category: "SEO Strategy", title: "Expertise Signals: Proving You Know Your Subject", subject: "expertise signals", hookA: "Claiming expertise is easy and meaningless. Demonstrating it through real signals is what convinces both search engines and the people reading your content.", whatIs: "Expertise signals are the indicators that show genuine knowledge and qualification behind content.", why: "Search engines and AI tools assess expertise to judge content quality. Clear expertise signals lift both rankings and reader trust.", steps: ["Attribute content to qualified authors.", "Demonstrate depth and accuracy in the content.", "Show credentials and relevant experience.", "Reference authoritative sources.", "Build a recognised presence in your field."], link: "our content services", faqA: "Attribute content to qualified authors, demonstrate genuine depth and accuracy, and show credentials. Expertise is proven through evidence in the content itself, not asserted in a tagline.", faqTopic: "expertise signals" },
  { slug: "authoritativeness-signals-seo", category: "SEO Strategy", title: "Authoritativeness Signals That Build Ranking Power", subject: "authoritativeness signals", hookA: "Authority is earned in the eyes of others, not declared by yourself. Building the right authoritativeness signals is how you become a recognised name in your field.", whatIs: "Authoritativeness signals show that others recognise your site as a leading source on a topic.", why: "Authority is largely about external validation. Citations, links, and mentions from respected sources build the authoritativeness search rewards.", steps: ["Earn links and mentions from respected sources.", "Build recognition within your industry.", "Publish definitive, widely cited content.", "Develop author and brand reputation.", "Maintain consistency across the web."], link: "our link building services", faqA: "Earn links and mentions from respected sources, publish definitive content, and build industry recognition. Authority comes largely from external validation, so what others say about you matters most.", faqTopic: "authoritativeness" },
  { slug: "trustworthiness-signals-seo", category: "SEO Strategy", title: "Trustworthiness Signals Every Site Needs", subject: "trustworthiness signals", hookA: "Trust is the foundation of E-E-A-T and the easiest part to overlook. A few clear signals can dramatically raise how much search engines and users trust your site.", whatIs: "Trustworthiness signals are the elements that show a site is safe, honest, and reliable.", why: "Trust underpins everything in E-E-A-T. Clear trust signals improve rankings, conversions, and how AI tools assess your content.", steps: ["Secure the site with HTTPS.", "Display clear contact and business information.", "Add transparent policies and disclosures.", "Show reviews and social proof.", "Keep content accurate and honest."], link: "our SEO services", faqA: "Secure your site, display clear contact and policy information, and show reviews and honest content. Trust is the foundation of E-E-A-T, and these signals are often the easiest wins to implement.", faqTopic: "trustworthiness signals" },
  { slug: "experience-signals-seo", category: "SEO Strategy", title: "Experience Signals: The First E in E-E-A-T", subject: "experience signals", hookA: "Google added a second E for experience because first-hand knowledge matters. Showing you have actually done the thing you write about now influences rankings.", whatIs: "Experience signals demonstrate genuine first-hand experience with the subject of your content.", why: "Google increasingly values content from people who have real experience. Showing it sets your content apart from generic, second-hand information.", steps: ["Share first-hand insights and examples.", "Include original photos, data, or results.", "Describe real processes and outcomes.", "Attribute content to people with experience.", "Avoid generic, second-hand summaries."], link: "our content services", faqA: "Share first-hand insights, original examples, and real results, and attribute content to people who have genuinely done the work. Experience is the newest E-E-A-T element and it sets content apart.", faqTopic: "experience signals" },
  { slug: "author-bio-optimization", category: "SEO Strategy", title: "Author Bio Optimisation for E-E-A-T", subject: "author bio optimisation", hookA: "The humble author bio is a surprisingly powerful E-E-A-T signal. Done well, it tells search engines and readers exactly why your content can be trusted.", whatIs: "Author bio optimisation builds credible author profiles that reinforce expertise and trust.", why: "Author bios connect content to real, qualified people. They strengthen E-E-A-T and help search and AI tools attribute expertise correctly.", steps: ["Write detailed, credible bios.", "Include relevant credentials and experience.", "Link to author profiles and social proof.", "Add Person schema for key authors.", "Keep bios consistent across the web."], link: "our content services", faqA: "Write detailed bios with relevant credentials, link to author profiles, and add Person schema. A strong bio connects your content to a real, qualified person, which reinforces E-E-A-T.", faqTopic: "author bios" },
  { slug: "about-page-seo-optimization", category: "SEO Strategy", title: "About Page Optimisation for Trust and SEO", subject: "about page optimisation", hookA: "Your about page is one of the most visited and most underused pages on your site. Optimised properly, it builds trust and reinforces who you are to search engines.", whatIs: "About page optimisation strengthens the page that establishes your brand's identity and credibility.", why: "The about page is a key trust and entity signal. A strong one reassures visitors and helps search engines understand your brand.", steps: ["Clearly explain who you are and what you do.", "Share your story, team, and credentials.", "Add trust signals and social proof.", "Include Organization schema.", "Make contact information easy to find."], link: "our SEO services", faqA: "Clearly explain who you are, share your team and credentials, and add trust signals and Organization schema. The about page is a key trust and entity signal that many sites neglect.", faqTopic: "about page optimisation" },
  { slug: "building-brand-authority-seo", category: "SEO Strategy", title: "Building Brand Authority That Search Engines Notice", subject: "building brand authority", hookA: "Strong brands rank more easily, get cited more often, and convert better. Building genuine brand authority is one of the most durable SEO investments you can make.", whatIs: "Building brand authority develops the recognition and trust that strengthen every part of your search presence.", why: "Brand authority improves rankings, click-through, and AI citations. A recognised brand earns trust that generic competitors cannot match.", steps: ["Build consistent brand presence across the web.", "Earn mentions and coverage in your industry.", "Publish authoritative, original content.", "Develop a recognisable voice and identity.", "Grow branded search demand over time."], link: "our SEO services", faqA: "Build a consistent presence across the web, earn industry mentions, and publish authoritative content. Brand authority improves rankings, click-through, and AI citations, making it a durable investment.", faqTopic: "brand authority" },
  { slug: "thought-leader-seo-strategy", category: "SEO Strategy", title: "Thought Leader SEO: Building Personal Authority", subject: "thought leader SEO", hookA: "In many industries, people trust people more than logos. Building personal authority for your key experts can become one of your strongest SEO assets.", whatIs: "Thought leader SEO builds the search presence and authority of individual experts within a brand.", why: "Recognised experts strengthen E-E-A-T and earn citations. Personal authority also opens doors to coverage, links, and AI recommendations.", steps: ["Build expert profiles and presence.", "Publish original insight under their name.", "Earn speaking, podcast, and media opportunities.", "Use Person schema and consistent profiles.", "Connect personal authority to brand content."], link: "our content services", faqA: "Build your experts' profiles, publish original insight under their names, and pursue media and podcast opportunities. Personal authority strengthens E-E-A-T and earns citations brands alone cannot.", faqTopic: "thought leader SEO" },
  { slug: "credentials-impact-on-seo", category: "SEO Strategy", title: "How Credentials Influence SEO and E-E-A-T", subject: "the impact of credentials on SEO", hookA: "Credentials are not just for resumes. In E-E-A-T-sensitive niches, displaying real qualifications can directly influence whether your content ranks.", whatIs: "This guide explains how professional credentials affect E-E-A-T and search performance.", why: "Credentials signal genuine expertise, especially in YMYL niches. Displaying them clearly strengthens trust and ranking potential.", steps: ["Display relevant credentials prominently.", "Connect credentials to specific content.", "Use author bios and schema to surface them.", "Verify and keep credentials current.", "Pair credentials with demonstrated expertise."], link: "our content services", faqA: "Display relevant credentials in author bios and schema, and connect them to the content they support. In YMYL niches especially, verifiable qualifications strengthen both trust and ranking potential.", faqTopic: "credentials and SEO" },
  { slug: "media-mentions-seo-guide", category: "Link Building", title: "Media Mentions and Their SEO Value", subject: "media mentions", hookA: "A mention in a respected publication does more than feel good. It builds authority, trust, and entity signals that ripple across your entire SEO presence.", whatIs: "Media mentions are references to your brand in news and industry publications, linked or not.", why: "Mentions in authoritative media build brand authority and entity recognition. They strengthen E-E-A-T and feed how AI tools understand your brand.", steps: ["Earn coverage through digital PR.", "Pursue mentions in relevant publications.", "Turn unlinked mentions into links where possible.", "Showcase coverage as trust signals.", "Track mentions and their impact."], link: "our link building services", faqA: "Earn coverage through digital PR and journalist outreach, then turn unlinked mentions into links where possible. Authoritative mentions build brand authority and entity signals that strengthen E-E-A-T.", faqTopic: "media mentions" },
  { slug: "eeat-audit-guide", category: "SEO Strategy", title: "The E-E-A-T Audit: Measuring Your Trust Signals", subject: "an E-E-A-T audit", hookA: "You cannot improve what you have not measured. An E-E-A-T audit reveals exactly where your experience, expertise, authority, and trust signals fall short.", whatIs: "An E-E-A-T audit systematically reviews the experience, expertise, authority, and trust signals across your site.", why: "An audit pinpoints the specific gaps holding back your credibility. It turns the abstract idea of E-E-A-T into a concrete action list.", steps: ["Review author attribution and bios.", "Assess content accuracy and sourcing.", "Check authority signals like links and mentions.", "Audit trust signals and policies.", "Prioritise gaps by impact."], link: "our content services", faqA: "Review author attribution, content accuracy, authority signals, and trust elements across your site. The audit turns the abstract idea of E-E-A-T into a concrete, prioritised list of improvements.", faqTopic: "E-E-A-T audits" },
];
