const analyticsGuides: GuideInput[] = [
  { slug: "seo-kpis-complete-guide", category: "Analytics", title: "SEO KPIs: The Metrics That Actually Matter", subject: "SEO KPIs", hookA: "Most SEO dashboards track everything and reveal nothing. The right KPIs cut through the noise and show whether your SEO is actually growing the business.", whatIs: "SEO KPIs are the key metrics that measure the success and business impact of your SEO.", why: "Tracking the right KPIs keeps SEO accountable to results. The wrong ones create busywork and hide whether the work is paying off.", steps: ["Focus on organic conversions and revenue.", "Track rankings for commercial terms.", "Monitor qualified organic traffic.", "Watch visibility across search surfaces.", "Tie every KPI to a business goal."], link: "our SEO services", faqA: "Focus on organic conversions, revenue, commercial rankings, and qualified traffic rather than vanity metrics. Every KPI should tie back to a business goal, or it is just noise.", faqTopic: "SEO KPIs" },
  { slug: "organic-traffic-analysis-guide", category: "Analytics", title: "Organic Traffic Analysis: Reading the Real Story", subject: "organic traffic analysis", hookA: "A traffic number alone tells you almost nothing. Real organic traffic analysis reveals which content works, which intent converts, and where the next opportunity sits.", whatIs: "Organic traffic analysis examines where your search traffic comes from and how it behaves.", why: "Analysis turns raw traffic into insight. It shows which pages, queries, and intents drive value, guiding where to invest next.", steps: ["Segment traffic by landing page and query.", "Analyse engagement and conversion by source.", "Identify your highest-value content.", "Spot declining pages early.", "Use insights to prioritise work."], link: "our SEO services", faqA: "Segment traffic by landing page, query, and intent, then analyse engagement and conversion. This reveals which content drives real value and where your next opportunities are, not just totals.", faqTopic: "traffic analysis" },
  { slug: "conversion-tracking-seo-guide", category: "Analytics", title: "Conversion Tracking for SEO Done Properly", subject: "conversion tracking for SEO", hookA: "If you cannot connect SEO to conversions, you cannot prove its value. Proper conversion tracking turns rankings and traffic into a clear revenue story.", whatIs: "Conversion tracking for SEO measures the actions organic visitors take that matter to your business.", why: "Tracking conversions links SEO to outcomes that matter. Without it, you are optimising traffic without knowing if it produces results.", steps: ["Define the conversions that matter.", "Set up accurate conversion tracking.", "Attribute conversions to organic traffic.", "Track micro and macro conversions.", "Report conversions, not just traffic."], link: "our SEO services", faqA: "Define your key conversions, set up accurate tracking, and attribute them to organic traffic. Without conversion tracking you are optimising traffic blindly, unable to prove SEO's real value.", faqTopic: "conversion tracking" },
  { slug: "revenue-attribution-seo", category: "Analytics", title: "Revenue Attribution: Connecting SEO to the Bottom Line", subject: "revenue attribution for SEO", hookA: "The most powerful SEO report shows revenue, not rankings. Revenue attribution connects organic search to actual money, which is the only metric that ends budget debates.", whatIs: "Revenue attribution connects organic search activity to the revenue it generates.", why: "Attributing revenue to SEO proves its return and secures investment. It moves the conversation from traffic to genuine business impact.", steps: ["Connect analytics to conversion and revenue data.", "Attribute revenue across the journey.", "Account for SEO's assisting role.", "Track revenue by landing page and query.", "Report SEO in revenue terms."], link: "our SEO services", faqA: "Connect analytics to conversion and revenue data, then attribute revenue across the journey while accounting for SEO's assisting role. Reporting in revenue terms ends budget debates.", faqTopic: "revenue attribution" },
  { slug: "seo-reporting-templates-guide", category: "Analytics", title: "SEO Reporting Templates That Communicate Value", subject: "SEO reporting templates", hookA: "A good SEO report answers three questions: what happened, why, and what next. The right template makes that clear to anyone, technical or not.", whatIs: "SEO reporting templates structure performance data into clear, repeatable reports.", why: "A strong template saves time and communicates value consistently. It keeps reporting focused on outcomes rather than data dumps.", steps: ["Lead with business outcomes.", "Show progress against goals.", "Explain the why behind the numbers.", "Include clear next steps.", "Keep it concise and audience-appropriate."], link: "our SEO services", faqA: "Use a template that leads with business outcomes, shows progress against goals, explains the why, and lists next steps. A good report communicates insight and value rather than dumping data.", faqTopic: "SEO reporting" },
  { slug: "monthly-seo-report-guide", category: "Analytics", title: "The Monthly SEO Report That Drives Decisions", subject: "the monthly SEO report", hookA: "Monthly SEO reports too often become slideshows of vanity metrics. A report built to drive decisions looks completely different, and far more useful.", whatIs: "A monthly SEO report summarises performance, insight, and planned actions over the past month.", why: "A focused monthly report keeps stakeholders aligned and work accountable. It turns data into decisions rather than decoration.", steps: ["Summarise performance against goals.", "Highlight wins and issues clearly.", "Explain what the data means.", "Outline next month's priorities.", "Keep it concise and outcome-focused."], link: "our SEO services", faqA: "Summarise performance against goals, highlight wins and issues, explain what the data means, and outline next month's priorities. The best monthly reports drive decisions rather than just present numbers.", faqTopic: "monthly reporting" },
  { slug: "seo-dashboard-setup-guide", category: "Analytics", title: "Building an SEO Dashboard You Will Actually Use", subject: "an SEO dashboard", hookA: "Most SEO dashboards are built once and never opened again. A dashboard that focuses on the few metrics that matter becomes a tool you check every week.", whatIs: "An SEO dashboard centralises your most important metrics in one live view.", why: "A focused dashboard gives instant visibility into performance. It keeps the team aligned on the metrics that actually matter.", steps: ["Choose a handful of key metrics.", "Pull data from reliable sources.", "Visualise trends, not snapshots.", "Make it accessible to the team.", "Refine it as priorities evolve."], link: "our SEO services", faqA: "Choose a handful of key metrics, pull from reliable sources, and visualise trends over time. A focused dashboard you check weekly beats a comprehensive one you build once and forget.", faqTopic: "SEO dashboards" },
  { slug: "share-of-voice-seo-guide", category: "Analytics", title: "Share of Voice: Measuring Your Search Visibility", subject: "share of voice in SEO", hookA: "Rankings for individual keywords miss the bigger picture. Share of voice shows how much of your market's search visibility you actually own compared to competitors.", whatIs: "Share of voice measures your visibility across a set of keywords relative to competitors.", why: "Share of voice gives a market-level view of your visibility. It shows whether you are gaining or losing ground against competitors overall.", steps: ["Define your target keyword set.", "Measure your visibility across it.", "Compare against key competitors.", "Track share of voice over time.", "Target gaps where competitors lead."], link: "our SEO services", faqA: "Define a target keyword set, measure your visibility across it, and compare against competitors. Share of voice gives a market-level view that individual rankings miss, showing if you are gaining ground.", faqTopic: "share of voice" },
  { slug: "seo-forecasting-guide", category: "Analytics", title: "SEO Forecasting: Setting Realistic Expectations", subject: "SEO forecasting", hookA: "Unrealistic SEO expectations kill good campaigns before they pay off. Sound forecasting sets achievable targets and protects the work from premature judgement.", whatIs: "SEO forecasting estimates the likely traffic and revenue outcomes of an SEO strategy.", why: "Forecasting aligns expectations and justifies investment. Realistic projections protect SEO from being judged too early or too harshly.", steps: ["Base forecasts on current data and trends.", "Account for competition and difficulty.", "Model conservative and optimistic scenarios.", "Factor in SEO's gradual timeline.", "Revisit forecasts as data comes in."], link: "our SEO services", faqA: "Base forecasts on current data, keyword opportunity, and difficulty, then model conservative and optimistic scenarios. Realistic projections align expectations and protect the work from premature judgement.", faqTopic: "SEO forecasting" },
  { slug: "traffic-drop-diagnosis-guide", category: "Analytics", title: "Diagnosing a Traffic Drop Step by Step", subject: "diagnosing a traffic drop", hookA: "A sudden traffic drop triggers panic, but panic does not fix it. A calm, systematic diagnosis finds the real cause and the right response.", whatIs: "Traffic drop diagnosis is the process of finding why organic traffic has fallen.", why: "Traffic drops have many possible causes. A systematic diagnosis pinpoints the real one so you fix the problem rather than guess.", steps: ["Confirm the drop is real, not a tracking issue.", "Check for algorithm updates.", "Review technical and indexing health.", "Look for ranking and SERP changes.", "Identify the cause before acting."], link: "our SEO services", faqA: "Confirm the drop is real, check for algorithm updates, and review technical health, indexing, and ranking changes. A systematic diagnosis finds the actual cause instead of guessing at fixes.", faqTopic: "traffic drops" },
  { slug: "ranking-drop-recovery-guide", category: "Analytics", title: "Recovering From a Ranking Drop", subject: "ranking drop recovery", hookA: "Lost rankings are not always lost for good. With the right diagnosis and response, most ranking drops can be recovered, and sometimes you come back stronger.", whatIs: "Ranking drop recovery is the process of regaining lost search positions.", why: "Most ranking drops are recoverable once you understand the cause. A structured response restores positions faster than trial and error.", steps: ["Diagnose the cause of the drop.", "Address technical or content issues.", "Improve the affected pages.", "Rebuild lost relevance or authority.", "Monitor recovery and adjust."], link: "our SEO services", faqA: "Diagnose the cause first, then address the technical, content, or authority issue behind it and improve the affected pages. Most ranking drops are recoverable with a structured, evidence-based response.", faqTopic: "ranking recovery" },
  { slug: "algorithm-update-impact-guide", category: "Analytics", title: "Assessing the Impact of a Google Algorithm Update", subject: "algorithm update impact", hookA: "Every major Google update sends the SEO world into a frenzy. A calm, structured assessment tells you whether an update actually affected you, and what to do about it.", whatIs: "This guide explains how to assess whether and how a Google update affected your site.", why: "Reacting to updates blindly causes more harm than good. A structured assessment shows the real impact and the right response.", steps: ["Confirm the update timing and type.", "Compare your performance against the timeline.", "Identify which pages and queries shifted.", "Understand what the update targeted.", "Respond based on evidence, not panic."], link: "our SEO services", faqA: "Confirm the update's timing and focus, compare it against your performance, and identify which pages shifted. Respond based on what the update targeted rather than reacting blindly to every fluctuation.", faqTopic: "algorithm updates" },
  { slug: "seo-competitor-benchmarking", category: "Analytics", title: "SEO Competitor Benchmarking That Reveals Opportunity", subject: "SEO competitor benchmarking", hookA: "Your competitors are quietly showing you exactly where the opportunities are. Benchmarking against them reveals the gaps you can exploit and the threats you should counter.", whatIs: "SEO competitor benchmarking compares your search performance against key competitors.", why: "Benchmarking reveals where competitors lead and where you can gain. It turns competitor data into a concrete opportunity list.", steps: ["Identify your real search competitors.", "Compare visibility, content, and links.", "Find gaps where competitors lead.", "Spot their weaknesses to exploit.", "Turn findings into an action plan."], link: "our SEO services", faqA: "Identify your real search competitors, then compare visibility, content, and links to find gaps you can exploit and weaknesses to target. Benchmarking turns competitor data into an opportunity list.", faqTopic: "competitor benchmarking" },
  { slug: "seo-budget-planning-guide", category: "Analytics", title: "SEO Budget Planning for Predictable Growth", subject: "SEO budget planning", hookA: "Underfunded SEO stalls, and overfunded SEO wastes money on the wrong things. Smart budget planning puts resources where they generate the most return.", whatIs: "SEO budget planning allocates resources across the activities that drive the most return.", why: "A clear budget keeps SEO consistent and focused. It prevents both underinvestment that stalls progress and spending on low-value work.", steps: ["Prioritise high-impact activities.", "Balance content, technical, and authority work.", "Plan for consistency over time.", "Account for tools and resources.", "Tie budget to expected return."], link: "our SEO services", faqA: "Prioritise high-impact activities, balance content, technical, and authority work, and plan for consistency. A clear budget prevents both underinvestment that stalls progress and waste on low-value work.", faqTopic: "SEO budgeting" },
  { slug: "client-seo-reporting-guide", category: "Analytics", title: "Client SEO Reporting That Builds Trust", subject: "client SEO reporting", hookA: "For agencies, reporting is where trust is won or lost. Clear, honest, outcome-focused reporting keeps clients confident and engagements long.", whatIs: "Client SEO reporting communicates progress and value to clients clearly and honestly.", why: "Good client reporting builds trust and retention. It connects the work to outcomes clients care about, in language they understand.", steps: ["Focus on business outcomes, not jargon.", "Show progress against agreed goals.", "Be transparent about challenges.", "Explain the value of the work done.", "Provide clear next steps."], link: "our SEO services", faqA: "Focus on business outcomes, show progress against agreed goals, and be transparent about challenges. Honest, outcome-focused reporting builds the trust that keeps client relationships long and strong.", faqTopic: "client reporting" },
];
