// ─── assemble final posts ───────────────────────────────────────────────────
function specToPost2(spec: Spec2, index: number): GenBlogPost {
  const { date, iso, updated } = dateFor2(index);
  const sections = [...spec.sections, CTA2];
  return {
    slug: spec.slug,
    category: spec.category,
    title: spec.title,
    excerpt: spec.excerpt,
    date,
    iso,
    updated,
    time: readingTime2(spec.hook, sections, spec.takeaway),
    intro: spec.hook,
    sections,
    takeaway: spec.takeaway,
    imageUrl: imgFor(spec.category, spec.slug),
    faqs: spec.faqs,
  };
}

// De-duplicate slugs defensively, then build.
const seen2 = new Set<string>();
export const generatedBlogPosts2: GenBlogPost[] = specs2
  .filter((s) => {
    if (seen2.has(s.slug)) return false;
    seen2.add(s.slug);
    return true;
  })
  .map((s, i) => specToPost2(s, i));

export const generatedBlogMeta2: Record<string, { title: string; desc: string }> = Object.fromEntries(
  generatedBlogPosts2.map((p) => [p.slug, { title: `${p.title} | SEODXB Blog`, desc: p.excerpt }]),
);
